INSERT INTO reviews.entity_reviews (id, target_entity_id, target_entity_type, reviewer_user_id, project_id, cohort_membership_id, session_event_id, service_blueprint_id, window_closes_at, rating, title, comment, reply_comment, reply_user_id, replied_at, created_at, updated_at, reviewer_team_id, revealed_at)
VALUES
  ('2b9b2350-af2d-4e37-acf5-a69ee3f34aed', '2bdebf14-f7dc-40af-acd8-fe22cb9916fd', 'user', '9e4c0d6c-1b26-48ff-ae0f-1202ebcf5a3d', '69d02c2d-697e-416e-a61f-6d93886c8f54', NULL, NULL, NULL, now() - interval '-192 hours', 4.90, 'Organised and quick to approve', 'Assets, logins and brand files were ready before kickoff, which saved us a week. Approvals were fast and specific, and every submission got a real answer rather than a thumbs-up.', NULL, NULL, NULL, now() - interval '480 hours', now() - interval '480 hours', '213dc9f8-3ad7-4f35-ac4b-baa674bf48b3', now() - interval '480 hours'),
  ('0c604eab-8ad6-467a-a206-60d9461dfde8', '213dc9f8-3ad7-4f35-ac4b-baa674bf48b3', 'team', '2bdebf14-f7dc-40af-acd8-fe22cb9916fd', '69d02c2d-697e-416e-a61f-6d93886c8f54', NULL, NULL, '11c2391b-1568-4ee2-aa84-10dd81d8ccf4', now() - interval '-192 hours', 5.00, 'The identity our whole launch now hangs off', 'Atelier Nova ran discovery properly — they interviewed our roasters before drawing a single mark. The final kit covered every packaging size we sell and the Webflow handoff took our developer an afternoon.', NULL, NULL, NULL, now() - interval '504 hours', now() - interval '504 hours', NULL, now() - interval '480 hours'),
  ('27936ada-5e95-4c11-acf3-d39c7ad16a7b', '1fee216e-a637-4619-a90a-4ae03bb1ed8b', 'user', '9e4c0d6c-1b26-48ff-ae0f-1202ebcf5a3d', '00ae4bbb-f9a9-482c-a123-438d934e3dae', NULL, NULL, NULL, now() - interval '456 hours', 4.90, 'Organised and quick to approve', 'Assets, logins and brand files were ready before kickoff, which saved us a week. Approvals were fast and specific, and every submission got a real answer rather than a thumbs-up.', NULL, NULL, NULL, now() - interval '1128 hours', now() - interval '1128 hours', '213dc9f8-3ad7-4f35-ac4b-baa674bf48b3', now() - interval '1128 hours'),
  ('4d59fb75-d875-4888-a7f2-6797e531d2c2', '213dc9f8-3ad7-4f35-ac4b-baa674bf48b3', 'team', '1fee216e-a637-4619-a90a-4ae03bb1ed8b', '00ae4bbb-f9a9-482c-a123-438d934e3dae', NULL, NULL, '11c2391b-1568-4ee2-aa84-10dd81d8ccf4', now() - interval '456 hours', 4.80, 'Structured, calm and genuinely strategic', 'Every stage ended with something I could put in front of my board. The concept routes were distinct rather than three variations of one idea, which made choosing easy. One extra revision round was needed on the wordmark.', NULL, NULL, NULL, now() - interval '1152 hours', now() - interval '1152 hours', NULL, now() - interval '1128 hours'),
  ('5e1cd98b-6d80-4972-a83d-18ed64c0ed3c', 'de29f2ce-0f36-4db5-a417-4edc88cedf83', 'user', '9e4c0d6c-1b26-48ff-ae0f-1202ebcf5a3d', '0e30357c-77a1-411d-abab-3bce599da59f', NULL, NULL, NULL, now() - interval '1056 hours', 4.70, 'Fair, responsive, good to work for', 'They answered questions within the day and kept the review circle small. One stage needed an extra round of internal sign-off on their side, which they flagged before it slipped.', NULL, NULL, NULL, now() - interval '1728 hours', now() - interval '1728 hours', '213dc9f8-3ad7-4f35-ac4b-baa674bf48b3', now() - interval '1728 hours'),
  ('ffbc72f6-1ba1-4a39-a5d4-b9283a983f13', '213dc9f8-3ad7-4f35-ac4b-baa674bf48b3', 'team', 'de29f2ce-0f36-4db5-a417-4edc88cedf83', '0e30357c-77a1-411d-abab-3bce599da59f', NULL, NULL, '11c2391b-1568-4ee2-aa84-10dd81d8ccf4', now() - interval '1056 hours', 5.00, 'A brand system, not just a logo', 'We came for a refresh and left with a system our product team can actually extend: tokens for colour and type, clear rules for illustration, and a guidelines document people genuinely read.', NULL, NULL, NULL, now() - interval '1752 hours', now() - interval '1752 hours', NULL, now() - interval '1728 hours'),
  ('3596153e-518a-4e81-a2e4-f41819727b0b', 'de29f2ce-0f36-4db5-a417-4edc88cedf83', 'user', '6ce1906f-caab-4708-a19e-df3d8960666e', '70348c4b-e402-43c8-aad2-dc55c2a57b2a', NULL, NULL, NULL, now() - interval '-360 hours', 5.00, 'A brief we could build from on day one', 'The scope arrived with references, constraints and a named decision-maker, and every stage was signed off inside two working days. Payment released the moment the work was accepted.', NULL, NULL, NULL, now() - interval '288 hours', now() - interval '288 hours', NULL, now() - interval '288 hours'),
  ('85c27b8d-3010-44ac-ad01-4daf8cbbd616', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', 'de29f2ce-0f36-4db5-a417-4edc88cedf83', '70348c4b-e402-43c8-aad2-dc55c2a57b2a', NULL, NULL, 'bccc7920-ca19-4f5f-aa0e-f572e1e8b029', now() - interval '-360 hours', 5.00, 'Our engineers adopted it the same week', 'Maris set up a token architecture that maps cleanly onto our codebase, and the theming contract made dark mode a configuration change. The accessibility checklist caught issues we had shipped for a year.', NULL, NULL, NULL, now() - interval '336 hours', now() - interval '336 hours', NULL, now() - interval '288 hours'),
  ('5109d094-4e7c-4265-af46-7b4ab8a689fb', '292e1827-f189-4f34-ab35-27c9f0320926', 'user', '6ce1906f-caab-4708-a19e-df3d8960666e', 'dfe7d73b-bd11-49fa-afc7-91d1728386d8', NULL, NULL, NULL, now() - interval '240 hours', 5.00, 'A brief we could build from on day one', 'The scope arrived with references, constraints and a named decision-maker, and every stage was signed off inside two working days. Payment released the moment the work was accepted.', NULL, NULL, NULL, now() - interval '912 hours', now() - interval '912 hours', NULL, now() - interval '912 hours'),
  ('b696c2e9-8649-4496-aeeb-9f173e5ac56c', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', '292e1827-f189-4f34-ab35-27c9f0320926', 'dfe7d73b-bd11-49fa-afc7-91d1728386d8', NULL, NULL, 'bccc7920-ca19-4f5f-aa0e-f572e1e8b029', now() - interval '240 hours', 4.90, 'The foundation we should have started with', 'Clear stage reviews, a component library that matches production, and an adoption guide our engineers actually followed. Pricing per ticket let us scale the second stage up without renegotiating anything.', NULL, NULL, NULL, now() - interval '936 hours', now() - interval '936 hours', NULL, now() - interval '912 hours'),
  ('6c6a39d5-f827-4364-a8b8-3e3f7b996de6', '35ce4987-15b3-4c38-a438-2bb9c35df15a', 'user', '6ce1906f-caab-4708-a19e-df3d8960666e', 'f9188f26-0805-42af-a3c9-8a308c361d89', NULL, NULL, NULL, now() - interval '888 hours', 5.00, 'A brief we could build from on day one', 'The scope arrived with references, constraints and a named decision-maker, and every stage was signed off inside two working days. Payment released the moment the work was accepted.', NULL, NULL, NULL, now() - interval '1560 hours', now() - interval '1560 hours', NULL, now() - interval '1560 hours'),
  ('71328678-2c64-4e0b-a2f5-3522c3491b1d', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', '35ce4987-15b3-4c38-a438-2bb9c35df15a', 'f9188f26-0805-42af-a3c9-8a308c361d89', NULL, NULL, 'bccc7920-ca19-4f5f-aa0e-f572e1e8b029', now() - interval '888 hours', 4.70, 'Excellent on tokens, thorough on docs', 'The token work is excellent and the documentation is the best we have received from a contractor. The component review stage ran a few days long, but the delay was communicated early and handled well.', 'Thank you for the patience on the component review stage. Two components needed a second accessibility pass, and I would rather ship a few days late than ship them wrong.', '6ce1906f-caab-4708-a19e-df3d8960666e', now() - interval '1536 hours', now() - interval '1584 hours', now() - interval '1536 hours', NULL, now() - interval '1560 hours'),
  ('c08b424d-d2be-4bb0-ae4e-ce4f2564a482', '2bdebf14-f7dc-40af-acd8-fe22cb9916fd', 'user', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', '50d29fc2-661c-4bff-a968-78e489b36cc9', NULL, NULL, NULL, now() - interval '-480 hours', 4.70, 'Fair, responsive, good to work for', 'They answered questions within the day and kept the review circle small. One stage needed an extra round of internal sign-off on their side, which they flagged before it slipped.', NULL, NULL, NULL, now() - interval '168 hours', now() - interval '168 hours', NULL, now() - interval '168 hours'),
  ('225d4aec-0232-4223-a432-24d60f8e38b5', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', 'freelancer', '2bdebf14-f7dc-40af-acd8-fe22cb9916fd', '50d29fc2-661c-4bff-a968-78e489b36cc9', NULL, NULL, '56b1183a-92e4-4f4d-a30e-1e983a201c6b', now() - interval '-480 hours', 5.00, 'Live in five days, exactly as promised', 'Juno shipped a fast, accessible landing page in the week we were promised, with the forms and analytics wired correctly first time. The Figma file is tidy enough that I can edit sections myself now.', NULL, NULL, NULL, now() - interval '216 hours', now() - interval '216 hours', NULL, now() - interval '168 hours'),
  ('8002b4d6-0847-4433-a591-e65070807cbd', 'b30145ef-f693-439c-a2c4-8b3db32a54a2', 'user', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', 'b8e7c0fd-45b7-4680-ab71-ceb72e78b0c2', NULL, NULL, NULL, now() - interval '360 hours', 5.00, 'A brief we could build from on day one', 'The scope arrived with references, constraints and a named decision-maker, and every stage was signed off inside two working days. Payment released the moment the work was accepted.', NULL, NULL, NULL, now() - interval '1032 hours', now() - interval '1032 hours', NULL, now() - interval '1032 hours'),
  ('c0713f8f-f3b6-42d4-a4bb-070114b34d0e', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', 'freelancer', 'b30145ef-f693-439c-a2c4-8b3db32a54a2', 'b8e7c0fd-45b7-4680-ab71-ceb72e78b0c2', NULL, NULL, '56b1183a-92e4-4f4d-a30e-1e983a201c6b', now() - interval '360 hours', 4.60, 'Fast turnaround and a clean build', 'The build scored well on performance from day one and the copy pass tightened our messaging considerably. We needed one small layout fix after launch, which was turned around within a day of asking.', 'Thank you, Miguel. The layout fix was on us: a breakpoint we missed on the pricing table. It is now in the checklist every landing page goes through before it ships.', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', now() - interval '1032 hours', now() - interval '1056 hours', now() - interval '1032 hours', NULL, now() - interval '1032 hours'),
  ('2f923f16-26fb-49d7-a615-6f5018b56699', '292e1827-f189-4f34-ab35-27c9f0320926', 'user', 'c7173d3f-8b15-4876-afbf-499d17513a44', '105661d9-0b78-40c0-af1f-5b9be5f2e1f2', NULL, NULL, NULL, now() - interval '-264 hours', 4.80, 'Decisive, generous with context', 'Feedback came as one consolidated round per stage rather than a drip of messages, and when something was out of scope they said so early and funded the extra stage without fuss.', NULL, NULL, NULL, now() - interval '384 hours', now() - interval '384 hours', 'edc2d943-8062-426a-a6f2-29fdc6b4363c', now() - interval '384 hours'),
  ('0f9ed003-3135-4244-a7e3-9b7dfa40695e', 'edc2d943-8062-426a-a6f2-29fdc6b4363c', 'team', '292e1827-f189-4f34-ab35-27c9f0320926', '105661d9-0b78-40c0-af1f-5b9be5f2e1f2', NULL, NULL, '2579bbc6-d14d-4c65-a5a5-350c3ab9510b', now() - interval '-264 hours', 4.80, 'Reliable, communicative, and the load test held', 'North Loop delivered the ingestion stage a week early and the replay design has already saved us once in production. The row-level security policies were reviewed with us line by line before shipping.', NULL, NULL, NULL, now() - interval '432 hours', now() - interval '432 hours', NULL, now() - interval '384 hours'),
  ('74dcfe86-759d-4b17-af53-30d89371fc49', 'b30145ef-f693-439c-a2c4-8b3db32a54a2', 'user', 'c7173d3f-8b15-4876-afbf-499d17513a44', '8d8d6089-00d3-4c28-aa62-80f3f6cc29ca', NULL, NULL, NULL, now() - interval '552 hours', 4.80, 'Decisive, generous with context', 'Feedback came as one consolidated round per stage rather than a drip of messages, and when something was out of scope they said so early and funded the extra stage without fuss.', NULL, NULL, NULL, now() - interval '1200 hours', now() - interval '1200 hours', 'edc2d943-8062-426a-a6f2-29fdc6b4363c', now() - interval '1200 hours'),
  ('cc92b9bb-e52c-46a4-a61d-d1e567669ace', 'edc2d943-8062-426a-a6f2-29fdc6b4363c', 'team', 'b30145ef-f693-439c-a2c4-8b3db32a54a2', '8d8d6089-00d3-4c28-aa62-80f3f6cc29ca', NULL, NULL, '2579bbc6-d14d-4c65-a5a5-350c3ab9510b', now() - interval '552 hours', 4.90, 'A realtime backend we trust in production', 'Every stage came with a written handoff and a working demo. The typed client removed a whole class of bugs from our frontend, and the deployment runbook meant our on-call rotation was ready on day one.', NULL, NULL, NULL, now() - interval '1248 hours', now() - interval '1248 hours', NULL, now() - interval '1200 hours'),
  ('a51bb5d7-583b-44dc-ab5a-98d56fe18772', '1fee216e-a637-4619-a90a-4ae03bb1ed8b', 'user', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', 'dc05d8b2-1a3f-4605-a7d2-605013f92283', NULL, NULL, NULL, now() - interval '-48 hours', 4.70, 'Fair, responsive, good to work for', 'They answered questions within the day and kept the review circle small. One stage needed an extra round of internal sign-off on their side, which they flagged before it slipped.', NULL, NULL, NULL, now() - interval '600 hours', now() - interval '600 hours', NULL, now() - interval '600 hours'),
  ('91da7998-d622-4839-aaaa-461623061bbf', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', 'freelancer', '1fee216e-a637-4619-a90a-4ae03bb1ed8b', 'dc05d8b2-1a3f-4605-a7d2-605013f92283', NULL, NULL, '871a653c-93a9-45f9-a35f-8d3a3a0d3457', now() - interval '-48 hours', 5.00, 'The launch film carried our whole campaign', 'Ren turned a rough brief into a film that felt expensive without being loud. The social cut-downs were ready alongside the master, and the sound design made the product feel physical on screen.', NULL, NULL, NULL, now() - interval '648 hours', now() - interval '648 hours', NULL, now() - interval '600 hours'),
  ('d0ce0d68-35df-452d-a166-4dd6517b7de3', 'de29f2ce-0f36-4db5-a417-4edc88cedf83', 'user', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', '4ea69c23-0551-4d66-a55e-3361514c78a4', NULL, NULL, NULL, now() - interval '1248 hours', 4.80, 'Decisive, generous with context', 'Feedback came as one consolidated round per stage rather than a drip of messages, and when something was out of scope they said so early and funded the extra stage without fuss.', NULL, NULL, NULL, now() - interval '1872 hours', now() - interval '1872 hours', NULL, now() - interval '1872 hours'),
  ('782b96e9-e73a-409a-a2f3-4747b2ec6ad0', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', 'freelancer', 'de29f2ce-0f36-4db5-a417-4edc88cedf83', '4ea69c23-0551-4d66-a55e-3361514c78a4', NULL, NULL, '871a653c-93a9-45f9-a35f-8d3a3a0d3457', now() - interval '1248 hours', 4.70, 'Beautiful work, very clear process', 'Storyboards and style frames were signed off before any rendering began, so there were no surprises at the end. We asked for one extra cut-down, which was quoted clearly and delivered within two days.', NULL, NULL, NULL, now() - interval '1944 hours', now() - interval '1944 hours', NULL, now() - interval '1872 hours'),
  ('4fce693f-2d29-46b6-a0d8-2f3919543da0', 'a4c25501-0fdd-4abe-a575-ff478daad4fc', 'team', '950d68d1-8777-4bbe-ae59-3343e3e7f858', NULL, '72a1e2f1-d113-4b52-a34d-4d2793e7a538', '8c76ff64-7ec3-4fd7-adcd-a55292ce6fdd', 'eaff7484-81fb-46d3-adb1-42da56453eb9', now() - interval '-408 hours', 5.00, 'An hour that changed how I present my work', 'Saoirse walked through every case study, cut three I was attached to, and explained exactly why. The written action plan arrived the next morning and I have been working through it ever since.', NULL, NULL, NULL, now() - interval '288 hours', now() - interval '288 hours', NULL, now() - interval '288 hours'),
  ('763cbf94-3e74-49db-a952-55d691570d3d', 'a4c25501-0fdd-4abe-a575-ff478daad4fc', 'team', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', NULL, '1fd143dd-3218-44a6-ac8e-653b6913bf8c', 'c59105c8-7c0f-4c2b-a86b-fea6622a6db9', 'eaff7484-81fb-46d3-adb1-42da56453eb9', now() - interval '144 hours', 4.80, 'Direct, kind and genuinely useful', 'I have had portfolio reviews before that were vague encouragement. This was specific: which projects to lead with, what to cut, and how to write the case studies so the decisions come across.', NULL, NULL, NULL, now() - interval '840 hours', now() - interval '840 hours', NULL, now() - interval '840 hours'),
  ('485ddd49-4dee-4854-a0e8-57af74f963c2', 'a4c25501-0fdd-4abe-a575-ff478daad4fc', 'team', '5b4f5d46-9d9a-4973-a8fd-bfa0b88e72cd', NULL, '10e268d9-8269-4644-a3f9-8b8b3b37211e', 'd2d92e62-03ae-4edb-abf7-3444d1461e2d', 'f882f878-11fa-4489-a8fa-f3f24055f2cb', now() - interval '-144 hours', 4.90, 'Six sessions worth more than a course', 'The growth plan from the first session shaped the whole block, and the async feedback between calls kept me moving. I left with a clear sense of the design decisions I am now trusted to make.', NULL, NULL, NULL, now() - interval '552 hours', now() - interval '552 hours', NULL, now() - interval '552 hours'),
  ('ce9d2e8b-a9d5-49dc-a886-28b156d9ec1a', 'a4c25501-0fdd-4abe-a575-ff478daad4fc', 'team', '950d68d1-8777-4bbe-ae59-3343e3e7f858', NULL, '51503ab3-7c3d-4c12-a0b4-e6255e13fadc', '782f87a0-0ce3-4df5-a18d-0a12eedee6c7', 'f882f878-11fa-4489-a8fa-f3f24055f2cb', now() - interval '696 hours', 4.80, 'Thoughtful mentorship with real structure', 'Each session built on the last and the notes afterwards meant nothing was lost. The feedback on my UX writing portfolio was specific enough to act on the same day, which is rare in mentoring.', NULL, NULL, NULL, now() - interval '1392 hours', now() - interval '1392 hours', NULL, now() - interval '1392 hours'),
  ('fbbf911e-412e-4c6d-a251-36481126190f', '2bdebf14-f7dc-40af-acd8-fe22cb9916fd', 'user', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', '4e9b204f-d2d6-42f8-a83c-39f96f4346a2', NULL, NULL, NULL, now() - interval '24 hours', 5.00, 'A brief we could build from on day one', 'The scope arrived with references, constraints and a named decision-maker, and every stage was signed off inside two working days. Payment released the moment the work was accepted.', NULL, NULL, NULL, now() - interval '648 hours', now() - interval '648 hours', NULL, now() - interval '648 hours'),
  ('af9246d1-42e3-4964-a12d-d58bf80f5736', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', 'freelancer', '2bdebf14-f7dc-40af-acd8-fe22cb9916fd', '4e9b204f-d2d6-42f8-a83c-39f96f4346a2', NULL, NULL, '7b1b3f95-50bb-4b14-a1fa-457bd622993a', now() - interval '24 hours', 5.00, 'Packaging that finally matches the coffee', 'Ren''s three routes were genuinely different directions, and the final artwork came with print-ready dielines our supplier accepted without a single query. The whole SKU family now feels like one brand.', NULL, NULL, NULL, now() - interval '720 hours', now() - interval '720 hours', NULL, now() - interval '648 hours'),
  ('2bbdbe1c-d80d-4bfb-a165-0b22bf825179', '1fee216e-a637-4619-a90a-4ae03bb1ed8b', 'user', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', 'ff702eb9-0f43-4512-ae28-40b77b749360', NULL, NULL, NULL, now() - interval '912 hours', 5.00, 'A brief we could build from on day one', 'The scope arrived with references, constraints and a named decision-maker, and every stage was signed off inside two working days. Payment released the moment the work was accepted.', NULL, NULL, NULL, now() - interval '1536 hours', now() - interval '1536 hours', NULL, now() - interval '1536 hours'),
  ('18e3d77f-d681-497e-afad-1955e475c684', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', 'freelancer', '1fee216e-a637-4619-a90a-4ae03bb1ed8b', 'ff702eb9-0f43-4512-ae28-40b77b749360', NULL, NULL, '7b1b3f95-50bb-4b14-a1fa-457bd622993a', now() - interval '912 hours', 4.70, 'Strong art direction and a tidy handoff', 'The concept presentation was clear about trade-offs between cost and finish, which helped us decide quickly. The supplier handoff pack saved our production manager days of back and forth.', NULL, NULL, NULL, now() - interval '1608 hours', now() - interval '1608 hours', NULL, now() - interval '1536 hours'),
  ('fc0fe065-0924-4cf8-af0d-6a0f6271bcfa', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', '3fc3da04-549b-4239-aca3-fa82f713dbaf', NULL, 'f159ccdb-1a54-49cc-ac94-a395aa5f383e', 'a61e7e22-27bf-4685-a0a8-43cc42ebd2af', '40d68e27-474f-4b56-a37e-1605cbc3fdb4', now() - interval '-312 hours', 4.90, 'The clearest two hours on tokens I have seen', 'Maris moved from principles to a working token set in two hours without losing anyone. The exercise files were practical and the recording meant our absent teammates could catch up the next day.', NULL, NULL, NULL, now() - interval '384 hours', now() - interval '384 hours', NULL, now() - interval '384 hours'),
  ('33d970cd-866d-46d0-ac90-aadffb73929a', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', '2e4274fb-e76b-4640-ad31-c66d7fbea842', NULL, '3d49808b-5318-43f4-a540-12dd5342cf4e', '207f2f52-a8be-47ed-afd2-ddf48a951d7f', '40d68e27-474f-4b56-a37e-1605cbc3fdb4', now() - interval '288 hours', 4.60, 'Useful for engineers, not just designers', 'As a backend engineer I expected to sit this out, but the session on theming contracts changed how I think about our API for preferences. The follow-up thread answered everything we raised afterwards.', NULL, NULL, NULL, now() - interval '984 hours', now() - interval '984 hours', NULL, now() - interval '984 hours'),
  ('ee256db1-39ac-48bc-a8a3-827765c30ee2', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', '35ce4987-15b3-4c38-a438-2bb9c35df15a', NULL, '2562e03b-d03d-4298-a9d9-272147fbd19e', 'f6e66aaa-390a-4ed1-acf8-6c9886a7f517', '40d68e27-474f-4b56-a37e-1605cbc3fdb4', now() - interval '1104 hours', 4.80, 'Well run and immediately applicable', 'Our product team used the workshop as a kickoff for our own system and the shared vocabulary helped immediately. Sixteen seats felt about right — there was still time for everyone''s questions.', NULL, NULL, NULL, now() - interval '1800 hours', now() - interval '1800 hours', NULL, now() - interval '1800 hours'),
  ('ef6f2591-153f-4eae-a0ec-52f3e3bde568', '4cfa4f66-9aa2-496b-a93d-994caac019c1', 'business', '6ce1906f-caab-4708-a19e-df3d8960666e', 'aa954528-434e-49e3-aabf-7592574daaa5', NULL, NULL, NULL, now() - interval '384 hours', 1.50, 'Scope grew every week', 'Three new screens appeared after the stage was locked, each described as a small tweak. When we raised a revision round the reply was that it should already have been included. Payment came late.', NULL, NULL, NULL, now() - interval '1056 hours', now() - interval '1056 hours', NULL, now() - interval '384 hours'),
  ('a4f54841-dca7-45f4-a8ca-abb321f71d96', '4cfa4f66-9aa2-496b-a93d-994caac019c1', 'business', '45a4c6ae-d818-45fd-a62b-db44f1f69eab', 'bb7ecf56-ca3b-44e3-a788-90d0385efc0d', NULL, NULL, NULL, now() - interval '672 hours', 2.00, 'Hard to get a decision', 'Approvals sat for days with no reply, then arrived as a list of changes from people who had not been on the kickoff call. The build shipped, but nearly a month later than planned through no fault of the plan.', NULL, NULL, NULL, now() - interval '1344 hours', now() - interval '1344 hours', NULL, now() - interval '672 hours'),
  ('b8db2b1c-095b-433b-a1a5-f7b635563935', '4cfa4f66-9aa2-496b-a93d-994caac019c1', 'business', 'bdff9d38-7124-4a49-af5d-c88eb4fe8b57', '443d02f5-355b-4146-add9-77c7bbc99d78', NULL, NULL, NULL, now() - interval '1032 hours', 1.00, 'Signed-off work reopened at the end', 'The storyboard and the animatic were both signed off in writing, then the final cut was called off-brief and the earlier approvals were set aside. Acceptance took three more weeks of back and forth.', NULL, NULL, NULL, now() - interval '1704 hours', now() - interval '1704 hours', NULL, now() - interval '1032 hours'),
  ('4e9f3e31-9070-43e0-a51a-246371046d22', '4cfa4f66-9aa2-496b-a93d-994caac019c1', 'business', '3fc3da04-549b-4239-aca3-fa82f713dbaf', '2654cfe2-3d4c-4633-a4b2-514c22c2ce5d', NULL, NULL, NULL, now() - interval '1584 hours', 1.50, 'Feedback without a brief', 'There was no written brief, only a call, and each round of feedback contradicted the one before it. We delivered a full set twice. Communication was polite, but nothing was decided until the last week.', NULL, NULL, NULL, now() - interval '2256 hours', now() - interval '2256 hours', NULL, now() - interval '1584 hours'),
  ('f00b3ab9-c424-4d48-a8f0-e703cab43652', '4cfa4f66-9aa2-496b-a93d-994caac019c1', 'business', '2e4274fb-e76b-4640-ad31-c66d7fbea842', 'd2cf9c12-07b2-4e33-ad61-677468ebccb5', NULL, NULL, NULL, now() - interval '2184 hours', 2.00, 'Unclear ownership on their side', 'Three different people asked for different priorities and nobody could settle them. The work was accepted in the end, but only after we escalated twice and wrote the acceptance criteria ourselves.', NULL, NULL, NULL, now() - interval '2856 hours', now() - interval '2856 hours', NULL, now() - interval '2184 hours')
